macro_rules! deps {
    () => {
        CfgPredicateIdentifier!();
        UnsupportedLiteralReason!();
        UnknownVersionLiteral!();
        InvalidPredicate!();
        ExpectedSingleVersionLiteral!();
        UnsupportedLiteral!();
        ExpectedVersionLiteral!();
        Condition!();
        ExpectedOneCfgPattern!();
    };
}

macro_rules! eval_condition {
    () => {
        deps!();
        # [doc = " Evaluate a cfg-like condition (with `any` and `all`), using `eval` to"] # [doc = " evaluate individual items."] pub fn eval_condition (cfg : & MetaItemInner , sess : & Session , features : Option < & Features > , eval : & mut impl FnMut (Condition) -> bool ,) -> bool { let dcx = sess . dcx () ; let cfg = match cfg { MetaItemInner :: MetaItem (meta_item) => meta_item , MetaItemInner :: Lit (MetaItemLit { kind : LitKind :: Bool (b) , .. }) => { return * b ; } _ => { dcx . emit_err (session_diagnostics :: UnsupportedLiteral { span : cfg . span () , reason : UnsupportedLiteralReason :: CfgBoolean , is_bytestr : false , start_point_span : sess . source_map () . start_point (cfg . span ()) , }) ; return false ; } } ; match & cfg . kind { MetaItemKind :: List (mis) if cfg . has_name (sym :: version) => { try_gate_cfg (sym :: version , cfg . span , sess , features) ; let (min_version , span) = match & mis [..] { [MetaItemInner :: Lit (MetaItemLit { kind : LitKind :: Str (sym , ..) , span , .. })] => { (sym , span) } [MetaItemInner :: Lit (MetaItemLit { span , .. }) | MetaItemInner :: MetaItem (MetaItem { span , .. }) ,] => { dcx . emit_err (session_diagnostics :: ExpectedVersionLiteral { span : * span }) ; return false ; } [..] => { dcx . emit_err (session_diagnostics :: ExpectedSingleVersionLiteral { span : cfg . span , }) ; return false ; } } ; let Some (min_version) = parse_version (* min_version) else { dcx . emit_warn (session_diagnostics :: UnknownVersionLiteral { span : * span }) ; return false ; } ; if sess . psess . assume_incomplete_release { RustcVersion :: current_overridable () > min_version } else { RustcVersion :: current_overridable () >= min_version } } MetaItemKind :: List (mis) => { for mi in mis . iter () { if mi . meta_item_or_bool () . is_none () { dcx . emit_err (session_diagnostics :: UnsupportedLiteral { span : mi . span () , reason : UnsupportedLiteralReason :: Generic , is_bytestr : false , start_point_span : sess . source_map () . start_point (mi . span ()) , }) ; return false ; } } match cfg . name () { Some (sym :: any) => mis . iter () . fold (false , | res , mi | res | eval_condition (mi , sess , features , eval)) , Some (sym :: all) => mis . iter () . fold (true , | res , mi | res & eval_condition (mi , sess , features , eval)) , Some (sym :: not) => { let [mi] = mis . as_slice () else { dcx . emit_err (session_diagnostics :: ExpectedOneCfgPattern { span : cfg . span }) ; return false ; } ; ! eval_condition (mi , sess , features , eval) } Some (sym :: target) => { if let Some (features) = features && ! features . cfg_target_compact () { feature_err (sess , sym :: cfg_target_compact , cfg . span , fluent_generated :: attr_parsing_unstable_cfg_target_compact ,) . emit () ; } mis . iter () . fold (true , | res , mi | { let Some (mut mi) = mi . meta_item () . cloned () else { dcx . emit_err (session_diagnostics :: CfgPredicateIdentifier { span : mi . span () , }) ; return false ; } ; if let [seg , ..] = & mut mi . path . segments [..] { seg . ident . name = Symbol :: intern (& format ! ("target_{}" , seg . ident . name)) ; } res & eval_condition (& MetaItemInner :: MetaItem (mi) , sess , features , eval) }) } _ => { dcx . emit_err (session_diagnostics :: InvalidPredicate { span : cfg . span , predicate : pprust :: path_to_string (& cfg . path) , }) ; false } } } MetaItemKind :: Word | MetaItemKind :: NameValue (..) if cfg . path . segments . len () != 1 => { dcx . emit_err (session_diagnostics :: CfgPredicateIdentifier { span : cfg . path . span }) ; true } MetaItemKind :: NameValue (lit) if ! lit . kind . is_str () => { dcx . emit_err (session_diagnostics :: UnsupportedLiteral { span : lit . span , reason : UnsupportedLiteralReason :: CfgString , is_bytestr : lit . kind . is_bytestr () , start_point_span : sess . source_map () . start_point (lit . span) , }) ; true } MetaItemKind :: Word | MetaItemKind :: NameValue (..) => { let ident = cfg . ident () . expect ("multi-segment cfg predicate") ; eval (Condition { name : ident . name , name_span : ident . span , value : cfg . value_str () , value_span : cfg . name_value_literal_span () , span : cfg . span , }) } } }
    };
}

eval_condition!();